<template>
    <div class="home-view">

        <div class="container">
            <el-container>
                <el-header>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;
                    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;附小常规巡查系统
                    <el-radio-group v-model="direction">

                    </el-radio-group>

                    <el-button @click="drawer = true" type="primary" style="margin-left: 16px;">
                        点击上传照片
                    </el-button>

                    <el-drawer title="我是标题" :visible.sync="drawer" :direction="direction" :before-close="handleClose">
                        <span>我来啦!</span>
                        <div>
                            <!-- 使用capture="camera"调用摄像头 -->
                            <button @click="triggerFileInput">上传图片</button>
                            <input type="file" accept="image/*" capture="camera" @change="handleFileChange"
                                style="display: none" ref="fileInput">

                            <!-- 图片缩略图展示区 -->
                            <div class="image-container" v-for="(image, index) in images" :key="index">
                                <img :src="image.url" class="thumbnail">
                                <div class="overlay" @mouseover="hover = true" @mouseleave="hover = false">
                                    <i class="icon el-icon-zoom-in" @click="handlePreview(image)"></i>
                                    <i class="icon el-icon-download" @click="handleDownload(image)"></i>
                                    <i class="icon el-icon-delete" @click="handleRemove(index)"></i>
                                </div>
                            </div>
                        </div>
                    </el-drawer>
                </el-header>
                <el-container>
                    <el-aside>
                        <el-menu router default-active="" unique-opened="true">
                            <template v-for="m1 of top">
                                <el-submenu v-if="m1.children" :key="m1.id" :index="m1.path">
                                    <span slot="title">
                                        <i :class="m1.icon"></i> {{ m1.name }}
                                    </span>
                                    <el-menu-item v-for="m2 of m1.children" :index="m2.path" :key="m2.id">
                                        <span slot="title">
                                            <i :class="m2.icon"></i> {{ m2.name }}
                                        </span>
                                    </el-menu-item>
                                </el-submenu>

                                <el-menu-item v-else :key="m1.id" :index="m1.path">
                                    <span slot="title">
                                        <i :class="m1.icon"></i> {{ m1.name }}
                                    </span>
                                </el-menu-item>

                            </template>
                        </el-menu>
                    </el-aside>
                    <el-main><router-view></router-view></el-main>
                </el-container>
            </el-container>
        </div>
    </div>
</template>

<script>
  import * as axios from '@/handler/prehand';
  import moment from 'moment';

const options = {
    mounted() {
        const serveRoutes = sessionStorage.getItem('serveRoutes');
        const array = JSON.parse(serveRoutes);

        const map = new Map();
        const top = [];
        for (const obj of array) {
            map.set(obj.id, obj);
        }

        for (const obj of array) {
            const parent = map.get(obj.pid);
            if (parent) {
                parent.children ??= [];
                parent.children.push(obj);
            } else {
                top.push(obj);
            }
        }

        this.top = top;


    },

    data() {
        return {
            top: [],
            drawer: false,
            direction: 'rtl',
            images: [], // 存储上传的图片信息
            hover: false, // 控制操作图标的显示
            checkdate: new Date(Date.now()),
        }
    },
    methods: {
        jump(url) {
            this.$router.push(url);
        },
    
    handleClose(done) {
        done();
    },



    triggerFileInput() {
        this.$refs.fileInput.click(); // 触发文件选择
      },
      async handleFileChange(event) {
        const file = event.target.files[0];
        if (file) {
          // 创建FormData对象并添加文件
          const formData = new FormData();
          formData.append('image', file); // 'image'是后端接收文件的参数名
          formData.append('checkDate',moment(this.checkdate).format("YYYY-MM-DD"))
          
          // 使用fetch或者axios发送POST请求到服务器上传文件
          // 假设上传URL是'http://example.com/upload'
                try {
                    axios.post('/tpi/uploadimg', formData).then(response => {
                        const resp = response.data.data;
                        if (resp) {
                            this.images.push({ url: resp }); // 使用服务器返回的URL
                        } else {
                            console.error('服务器没有返回图片URL');
                        }
                    })

                } catch (error) {
                    console.error('上传图片失败', error);
                }
            }
        },
      handlePreview(image) {
        console.log('Preview image', image);
        // 预览图片逻辑
      },
      handleDownload(image) {
        console.log('Download image', image);
        // 下载图片逻辑
      },
      handleRemove(index) {
        this.images.splice(index, 1); // 从列表中删除图片
      }
}}
export default options;
</script>
